(2809804, 391219, 51538, '<td valign="top">Nice profile and depth of field.  Lovely work. 8.</td>', 'Nice profile and depth of field.  Lovely work. 8.', '2006-09-07 10:55:09.000000', NULL, 1),
(2809811, 390856, 55358, '<td valign="top">i didn''t like it untill i saw the no fishing sign and started to laugh. maby you could make the sign and the rod more obvious.</td>', 'i didn''t like it untill i saw the no fishing sign and started to laugh. maby you could make the sign and the rod more obvious.', '2006-09-07 10:57:37.000000', NULL, 1),
(2809818, 391599, 43774, '<td valign="top">This is lovely, simple and charming. The only thing I can nit-pick is the hair on the flowers, I saw that right away. But it is still in my top 3 picks.</td>', 'This is lovely, simple and charming. The only thing I can nit-pick is the hair on the flowers, I saw that right away. But it is still in my top 3 picks.', '2006-09-07 10:59:19.000000', NULL, 1),
(2809820, 389216, 43774, '<td valign="top">Very cute. Not sure I like the sepia treatment or her cut off head, but otherwise it''s nice.</td>', 'Very cute. Not sure I like the sepia treatment or her cut off head, but otherwise it''s nice.', '2006-09-07 10:59:51.000000', NULL, 1),
(2809823, 391382, 55358, '<td valign="top">i think this is cute. fo some reason i wish it was blackand white. maby because the hat and the fence make the picture feel old.</td>', 'i think this is cute. fo some reason i wish it was blackand white. maby because the hat and the fence make the picture feel old.', '2006-09-07 11:00:30.000000', NULL, 1),
(2809826, 390968, 43774, '<td valign="top">Lovely view, I''ll take a simple pleasure like that any day! This reminds me of the scenery in "the Sound of Music".</td>', 'Lovely view, I''ll take a simple pleasure like that any day! This reminds me of the scenery in "the Sound of Music".', '2006-09-07 11:01:00.000000', NULL, 1),
(2809830, 391809, 43774, '<td valign="top">Lovely. I''ve always wanted to go on a hot air balloon ride. Love the lighting.</td>', 'Lovely. I''ve always wanted to go on a hot air balloon ride. Love the lighting.', '2006-09-07 11:01:50.000000', NULL, 1),
(2809835, 391186, 43774, '<td valign="top">Very very cute!! Love the lighting and colour. In my top 3!</td>', 'Very very cute!! Love the lighting and colour. In my top 3!', '2006-09-07 11:02:11.000000', NULL, 1),
(2810000, 388063, 62554, '<td valign="top">This is simply elegant!  Obviously a break during a camera club or similar shoot where the model is comfortably liaising with the members.  Simply pleasurable!  Picture this elegantly framed and hanging on your wall - I can!</td>', 'This is simply elegant!  Obviously a break during a camera club or similar shoot where the model is comfortably liaising with the members.  Simply pleasurable!  Picture this elegantly framed and hanging on your wall - I can!', '2006-09-07 11:47:18.000000', NULL, 1),
(2810104, 388063, 32345, '<td valign="top">LOL</td>', 'LOL', '2006-09-07 12:26:23.000000', NULL, 1),
(2810218, 391584, 64175, '<td valign="top">Wonderful depth of field. Great greens.</td>', 'Wonderful depth of field. Great greens.', '2006-09-07 13:08:10.000000', NULL, 1),
(2810232, 391491, 64175, '<td valign="top">While the subject appears to be the tree, it may not have enough character to draw you to it.</td>', 'While the subject appears to be the tree, it may not have enough character to draw you to it.', '2006-09-07 13:12:14.000000', NULL, 1),
(2810238, 391103, 18780, '<td valign="top">Bit hot on the arms but nothing you could do about that...love your dry sense of humor</td>', 'Bit hot on the arms but nothing you could do about that...love your dry sense of humor', '2006-09-07 13:13:39.000000', NULL, 1),
(2810242, 391568, 64175, '<td valign="top">This shot is great, but I think what may have made it better is if no one or only the two sitting persons where on the hill.</td>', 'This shot is great, but I think what may have made it better is if no one or only the two sitting persons where on the hill.', '2006-09-07 13:14:09.000000', NULL, 1),
(2810282, 390036, 60910, '<td valign="top">i think this is a perfect example of a simple pleasure... wonderfully done, love the b/w and your composition is excellent... very nice..</td>', 'i think this is a perfect example of a simple pleasure... wonderfully done, love the b/w and your composition is excellent... very nice..', '2006-09-07 13:21:51.000000', NULL, 1),
(2810291, 388505, 18780, '<td valign="top">Would like to have seen a tighter crop on the figures...background detracts from the tenderness of the moment.</td>', 'Would like to have seen a tighter crop on the figures...background detracts from the tenderness of the moment.', '2006-09-07 13:23:28.000000', NULL, 1),
(2810304, 390022, 18780, '<td valign="top">Colors/saturation are nice</td>', 'Colors/saturation are nice', '2006-09-07 13:24:54.000000', NULL, 1),
(2810311, 391640, 18780, '<td valign="top">Interesting cropping</td>', 'Interesting cropping', '2006-09-07 13:26:24.000000', NULL, 1),
(2810320, 391743, 18780, '<td valign="top">Good exposure but hair strands add what?</td>', 'Good exposure but hair strands add what?', '2006-09-07 13:27:29.000000', NULL, 1),
(2810414, 390601, 64175, '<td valign="top">Creative title, but the photo itself does not really stand out.</td>', 'Creative title, but the photo itself does not really stand out.', '2006-09-07 13:47:38.000000', NULL, 1),
(2810416, 389089, 64175, '<td valign="top">Sorry, Cats come with a handicap in my book.</td>', 'Sorry, Cats come with a handicap in my book.', '2006-09-07 13:48:08.000000', NULL, 1),
(2810421, 391016, 64175, '<td valign="top">Cats come with a handicap in my book ,but I really like the photo.</td>', 'Cats come with a handicap in my book ,but I really like the photo.', '2006-09-07 13:48:48.000000', NULL, 1),
