INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2823383, 389725, 26906, '<td valign="top">as a glamour shot, this is horrible. as a "simple pleasures" entry it is very puzzling.</td>', 'as a glamour shot, this is horrible. as a "simple pleasures" entry it is very puzzling.', '2006-09-11 11:32:59.000000', NULL, 1),
(2823387, 389669, 26906, '<td valign="top">oh yeah, sure, i believe it. the girl finds a pleasure of coming to railway tracks every sunrize and blast her guitar away...</td>', 'oh yeah, sure, i believe it. the girl finds a pleasure of coming to railway tracks every sunrize and blast her guitar away...', '2006-09-11 11:34:27.000000', NULL, 1),
(2823392, 390922, 26906, '<td valign="top">it looks fakely staged</td>', 'it looks fakely staged', '2006-09-11 11:34:53.000000', NULL, 1),
(2823687, 390357, 60329, '<td valign="top">The sofa (cushions?) in the background is distracting, but the sentiment is right.</td>', 'The sofa (cushions?) in the background is distracting, but the sentiment is right.', '2006-09-11 13:01:25.000000', NULL, 1),
(2823690, 391579, 60329, '<td valign="top">Seems the focus here is not correct and should be on the swing and not the chain.</td>', 'Seems the focus here is not correct and should be on the swing and not the chain.', '2006-09-11 13:01:45.000000', NULL, 1),
(2823693, 391186, 60329, '<td valign="top">A little washed out - the colours could pop more. Nice composition.</td>', 'A little washed out - the colours could pop more. Nice composition.', '2006-09-11 13:02:10.000000', NULL, 1),
(2823789, 390219, 33672, '<td valign="top">My pick to win the blue. great comp and lighting as well as an interesting subject. Nice colors and tones (results of almost perfect lighting!) 10</td>', 'My pick to win the blue. great comp and lighting as well as an interesting subject. Nice colors and tones (results of almost perfect lighting!) 10', '2006-09-11 13:31:04.000000', NULL, 1),
(2823792, 390689, 33672, '<td valign="top">Great comp and idea. colors really pop out at me.</td>', 'Great comp and idea. colors really pop out at me.', '2006-09-11 13:31:41.000000', NULL, 1),
(2823798, 390067, 33672, '<td valign="top">Great idea and expression. nice comp and lighting.</td>', 'Great idea and expression. nice comp and lighting.', '2006-09-11 13:32:39.000000', NULL, 1),
(2823806, 389805, 33672, '<td valign="top">Priceless capture! soft focus isn''t one of my favorites but tjis works really nicely.</td>', 'Priceless capture! soft focus isn''t one of my favorites but tjis works really nicely.', '2006-09-11 13:35:24.000000', NULL, 1),
(2823808, 391806, 33672, '<td valign="top">Great idea that''s a bit too dark.</td>', 'Great idea that''s a bit too dark.', '2006-09-11 13:35:58.000000', NULL, 1),
(2823816, 391720, 33672, '<td valign="top">Great comp and capture.  Seems a bit over saturated (The vest)but an outstanding photo none the less.</td>', 'Great comp and capture.  Seems a bit over saturated (The vest)but an outstanding photo none the less.', '2006-09-11 13:38:21.000000', NULL, 1),
(2823817, 391675, 33672, '<td valign="top">Very cute nice choice with the B&amp;W</td>', 'Very cute nice choice with the B&W', '2006-09-11 13:38:47.000000', NULL, 1),
(2823832, 389157, 43115, '<td valign="top">Too small, harsh lighting, busy background.  Check out the tutorials under "Learn" and browse some past ribbon winners for ideas.</td>', 'Too small, harsh lighting, busy background.  Check out the tutorials under "Learn" and browse some past ribbon winners for ideas.', '2006-09-11 13:49:30.000000', NULL, 1),
(2823833, 390950, 43115, '<td valign="top">The harsh lighting on this shot really kills it.  This scene cries for some moody, soft light.</td>', 'The harsh lighting on this shot really kills it.  This scene cries for some moody, soft light.', '2006-09-11 13:50:00.000000', NULL, 1),
(2823834, 389089, 43115, '<td valign="top">Too small. :( Check out the tutorials under "Learn" and browse some past ribbon winners for ideas.</td>', 'Too small. :( Check out the tutorials under "Learn" and browse some past ribbon winners for ideas.', '2006-09-11 13:50:13.000000', NULL, 1),
(2823837, 389528, 43115, '<td valign="top">The flash reflection in the pup''s eyes really kills this shot.  Otherwise it could be quite cute!  Also, the white thing in the background is really distracting... clean up your stage before you shoot!</td>', 'The flash reflection in the pup''s eyes really kills this shot.  Otherwise it could be quite cute!  Also, the white thing in the background is really distracting... clean up your stage before you shoot!', '2006-09-11 13:51:09.000000', NULL, 1),
(2823843, 390602, 43115, '<td valign="top">Cute, but doesn''t really tell me anything.  What is the pleasure, being the boss?  It is well lit and set up.</td>', 'Cute, but doesn''t really tell me anything.  What is the pleasure, being the boss?  It is well lit and set up.', '2006-09-11 13:51:54.000000', NULL, 1),
(2823847, 391552, 43115, '<td valign="top">This is a very awkward pose and just looks uncomfortable.  Also the shot lacks sharpness, probably poor focus.</td>', 'This is a very awkward pose and just looks uncomfortable.  Also the shot lacks sharpness, probably poor focus.', '2006-09-11 13:52:34.000000', NULL, 1),
(2823887, 390972, 43115, '<td valign="top">Overall well done, but the lighting seems a little harsh on the hand.</td>', 'Overall well done, but the lighting seems a little harsh on the hand.', '2006-09-11 14:05:50.000000', NULL, 1),
(2823890, 390175, 43115, '<td valign="top">Great, great, great photo.  I love the "pose" the DOF used, the calm muted tones, the nice even lighting.  Well done!</td>', 'Great, great, great photo.  I love the "pose" the DOF used, the calm muted tones, the nice even lighting.  Well done!', '2006-09-11 14:06:26.000000', NULL, 1),
(2823891, 390439, 43115, '<td valign="top">I love the way he is looking down at the baby instead of into the camera.</td>', 'I love the way he is looking down at the baby instead of into the camera.', '2006-09-11 14:06:56.000000', NULL, 1),
(2823895, 390946, 43115, '<td valign="top">Great use of DOF.  A lot of similar entries have stupid backgrounds, like the kitchen table or something, but your use of macro and DOF eliminates that problem.  Great lighting too!</td>', 'Great use of DOF.  A lot of similar entries have stupid backgrounds, like the kitchen table or something, but your use of macro and DOF eliminates that problem.  Great lighting too!', '2006-09-11 14:07:44.000000', NULL, 1),
(2823897, 390886, 43115, '<td valign="top">I think I would have preferred to see either more, or less, of the fondue fountain.  The way the shot is composed now is a little unsettling.</td>', 'I think I would have preferred to see either more, or less, of the fondue fountain.  The way the shot is composed now is a little unsettling.', '2006-09-11 14:08:39.000000', NULL, 1),
(2823898, 390968, 43115, '<td valign="top">Beautiful landscape!  Looks almost like a painting.  Even more impressive that you were able to get such dynamic range without spot editing.  Good job!</td>', 'Beautiful landscape!  Looks almost like a painting.  Even more impressive that you were able to get such dynamic range without spot editing.  Good job!', '2006-09-11 14:09:24.000000', NULL, 1),
(2823899, 390403, 43115, '<td valign="top">Well staged and very likable photo.  Good job!</td>', 'Well staged and very likable photo.  Good job!', '2006-09-11 14:09:46.000000', NULL, 1),
(2823901, 391426, 20056, '<td valign="top">What is the race of the cat?... We are looking for a cat since long and we like very much yours.<br/>About the picture: I think is a very good idea, maybe I wouldn''t crop your feet and put another color in the bed because pure white is very dificult to manage in a picture</td>', 'What is the race of the cat?... We are looking for a cat since long and we like very much yours.About the picture: I think is a very good idea, maybe I wouldn''t crop your feet and put another color in the bed because pure white is very dificult to manage in a picture', '2006-09-11 14:10:29.000000', NULL, 1),
(2823902, 390036, 43115, '<td valign="top">I really like the mild grunge feeling to this photo.  It looks a bit like one of the old Cindy Crawford adverts.  The sharp contrast does well here.</td>', 'I really like the mild grunge feeling to this photo.  It looks a bit like one of the old Cindy Crawford adverts.  The sharp contrast does well here.', '2006-09-11 14:10:37.000000', NULL, 1),
(2823906, 391518, 30049, '<td valign="top">Very well put together.  I like the tone of the early/late day sun here.  You did a nice job exposing for it.  Good luck in the challenge.</td>', 'Very well put together.  I like the tone of the early/late day sun here.  You did a nice job exposing for it.  Good luck in the challenge.', '2006-09-11 14:11:42.000000', NULL, 1),
(2823907, 390730, 43115, '<td valign="top">Very nice shot, and the silhouette works quite well here.</td>', 'Very nice shot, and the silhouette works quite well here.', '2006-09-11 14:11:43.000000', NULL, 1),
(2823909, 391225, 43115, '<td valign="top">Simple, makes a statement with stong visual impact.  Good job!</td>', 'Simple, makes a statement with stong visual impact.  Good job!', '2006-09-11 14:11:59.000000', NULL, 1),
(2823910, 389841, 20056, '<td valign="top">I like it...maybe too much red.</td>', 'I like it...maybe too much red.', '2006-09-11 14:12:00.000000', NULL, 1),
(2823911, 391223, 20056, '<td valign="top">Amen :)</td>', 'Amen :)', '2006-09-11 14:12:23.000000', NULL, 1),
(2823915, 391765, 20056, '<td valign="top">I would crop the upper part</td>', 'I would crop the upper part', '2006-09-11 14:14:39.000000', NULL, 1),
(2823917, 390036, 20056, '<td valign="top">nice pp work and better idea</td>', 'nice pp work and better idea', '2006-09-11 14:15:30.000000', NULL, 1),
(2823923, 390972, 30049, '<td valign="top">Ah, yes.  That IS a simple pleasure, and dangerous too!  ;^)  That''s why my alarm clock is on the other side of the room.  He-he.  As far as your image goes, it''s composed just fine.  I like the angle and it even works in a square crop as you''ve done.  Exposure, clarity, focus...all fine.  I know it''s hard, but images can really show the dirt/dust that you barely see with the naked eye.  That''s my only complaint (a minor one at that) - a little more attention to detail would probably boost this .5 to 1 point in scoring.<br/> <br/>Best of luck to you in the challenge.</td>', 'Ah, yes.  That IS a simple pleasure, and dangerous too!  ;^)  That''s why my alarm clock is on the other side of the room.  He-he.  As far as your image goes, it''s composed just fine.  I like the angle and it even works in a square crop as you''ve done.  Exposure, clarity, focus...all fine.  I know it''s hard, but images can really show the dirt/dust that you barely see with the naked eye.  That''s my only complaint (a minor one at that) - a little more attention to detail would probably boost this .5 to 1 point in scoring. Best of luck to you in the challenge.', '2006-09-11 14:16:22.000000', NULL, 1),
(2823935, 388063, 30049, '<td valign="top">Sorry, but this is just plain weird.</td>', 'Sorry, but this is just plain weird.', '2006-09-11 14:19:31.000000', NULL, 1),
(2823943, 390403, 30049, '<td valign="top">Awwww...now this is sweet!  ;^)  And not a bad image either.  He-he.  In for a penny, in for a pound...should have shown the beer bottle label.  Might have helped to drop the blue tone some - it''s a bit overpowering and gives a cool cast to what should be a warmer color temp image.  JMO of course.  ;^)<br/> <br/>Nice idea.  Good luck in the challenge.</td>', 'Awwww...now this is sweet!  ;^)  And not a bad image either.  He-he.  In for a penny, in for a pound...should have shown the beer bottle label.  Might have helped to drop the blue tone some - it''s a bit overpowering and gives a cool cast to what should be a warmer color temp image.  JMO of course.  ;^) Nice idea.  Good luck in the challenge.', '2006-09-11 14:22:41.000000', NULL, 1),
(2823950, 389089, 61679, '<td valign="top">Back to comment:  I think you may want to re-read the posting guidelines, as this image is much smaller than what is allowed.  Although your entry fits well in the Simple Pleasures challenge, it is hard judge the technical merits of your image when it is this small.  As presented, it appears that the image is a little out of focus.  This could be a result of not sharpening the image after downsizing it or from operation of the camera.</td>', 'Back to comment:  I think you may want to re-read the posting guidelines, as this image is much smaller than what is allowed.  Although your entry fits well in the Simple Pleasures challenge, it is hard judge the technical merits of your image when it is this small.  As presented, it appears that the image is a little out of focus.  This could be a result of not sharpening the image after downsizing it or from operation of the camera.', '2006-09-11 14:24:29.000000', NULL, 1),
(2823960, 388779, 61679, '<td valign="top">Back to comment: Although your entry fits well in the Simple Pleasures challenge, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing, camera shake, or a result of compressing the file too much (Your image 76 kb - allowable size 150 kb).</td>', 'Back to comment: Although your entry fits well in the Simple Pleasures challenge, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing, camera shake, or a result of compressing the file too much (Your image 76 kb - allowable size 150 kb).', '2006-09-11 14:27:03.000000', NULL, 1),
(2823983, 391263, 61679, '<td valign="top">Back to comment: Although your entry fits well in the Simple Pleasures challenge, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing or camera shake (Not using a tripod in low light conditions).</td>', 'Back to comment: Although your entry fits well in the Simple Pleasures challenge, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing or camera shake (Not using a tripod in low light conditions).', '2006-09-11 14:33:48.000000', NULL, 1),
(2823984, 391002, 61679, '<td valign="top">Back to comment:  Sorry to say but this subject is not the strongest choice for this challenge.  I also don''t care for the beak being cut off.</td>', 'Back to comment:  Sorry to say but this subject is not the strongest choice for this challenge.  I also don''t care for the beak being cut off.', '2006-09-11 14:33:53.000000', NULL, 1),
(2823991, 391657, 61679, '<td valign="top">Back to comment:  Although this subject fits the challenge well, there are several technical issues that hurt your score.  First, the horizon is not level.  Second, the image has a lot of noise (looks grainy in film jargon).  There are free programs available to reduce noise if you do an Internet search.  Third, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing, camera shake (Not using a tripod in low light conditions), or not taking full use of the allowable file (Your file 29 kb - Allowable file size 150 kb).</td>', 'Back to comment:  Although this subject fits the challenge well, there are several technical issues that hurt your score.  First, the horizon is not level.  Second, the image has a lot of noise (looks grainy in film jargon).  There are free programs available to reduce noise if you do an Internet search.  Third, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing, camera shake (Not using a tripod in low light conditions), or not taking full use of the allowable file (Your file 29 kb - Allowable file size 150 kb).', '2006-09-11 14:35:34.000000', NULL, 1),
(2824003, 391552, 61679, '<td valign="top">Back to comment: Sorry to say but this image doesn''t really convey Simple Pleasures to me.  She doesn''t really look all that happy and there is no indication of what is bringing her pleasure.  On the technical side, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing or from camera shake (Not using a tripod in low light conditions).</td>', 'Back to comment: Sorry to say but this image doesn''t really convey Simple Pleasures to me.  She doesn''t really look all that happy and there is no indication of what is bringing her pleasure.  On the technical side, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing or from camera shake (Not using a tripod in low light conditions).', '2006-09-11 14:37:45.000000', NULL, 1),
(2824021, 389669, 61679, '<td valign="top">Back to comment: Sorry to say but this image would have conveyed Simple Pleasures to me better if she had been sitting under a tree or by some water.  Railroad tracks are generally dirty and few people I know would be willing to sit on them to play a guitar.  On the technical side, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing or from poor focusing.</td>', 'Back to comment: Sorry to say but this image would have conveyed Simple Pleasures to me better if she had been sitting under a tree or by some water.  Railroad tracks are generally dirty and few people I know would be willing to sit on them to play a guitar.  On the technical side, it appears that the image is out of focus.  This could be a result of not sharpening the image after resizing or from poor focusing.', '2006-09-11 14:41:15.000000', NULL, 1),
(2824035, 388574, 61679, '<td valign="top">Back to comment:  You choose a very lovely subject for this challenge; however, your image suffers from a couple of technical issues.  First, the focus needs to be sharp on the girl''s eyes.  In your image the legs of the bear are in sharper focus than the girls eyes.  Second, the backdrop should be free of folds and wrinkles or so wrinkled that it looks intentional.</td>', 'Back to comment:  You choose a very lovely subject for this challenge; however, your image suffers from a couple of technical issues.  First, the focus needs to be sharp on the girl''s eyes.  In your image the legs of the bear are in sharper focus than the girls eyes.  Second, the backdrop should be free of folds and wrinkles or so wrinkled that it looks intentional.', '2006-09-11 14:44:34.000000', NULL, 1),
(2824048, 389714, 61679, '<td valign="top">Back to comment: Sorry, an image of what looks like a homeless person doesn''t convey Simple Pleasure to me.  Even if he isn''t homeless, he looks like he could be.  Your image suffers from a couple of technical issues as well.  First, the person on the left edge of the image should be cropped out.  Second, the statue looks tilted to the left.  Third, your black and white conversion looks flat and could use more contrast.</td>', 'Back to comment: Sorry, an image of what looks like a homeless person doesn''t convey Simple Pleasure to me.  Even if he isn''t homeless, he looks like he could be.  Your image suffers from a couple of technical issues as well.  First, the person on the left edge of the image should be cropped out.  Second, the statue looks tilted to the left.  Third, your black and white conversion looks flat and could use more contrast.', '2006-09-11 14:49:14.000000', NULL, 1),
(2824052, 391674, 61679, '<td valign="top">Back to comment: Sorry to be so blunt but I don''t see anything related to Simple Pleasures in this image.  Your image also has no focal point to hold the viewer''s attention.  Plus, the horizon is tilted very badly.</td>', 'Back to comment: Sorry to be so blunt but I don''t see anything related to Simple Pleasures in this image.  Your image also has no focal point to hold the viewer''s attention.  Plus, the horizon is tilted very badly.', '2006-09-11 14:51:47.000000', NULL, 1),
(2824058, 391308, 61679, '<td valign="top">Back to comment: Sorry to be so blunt but without the title, I wouldn''t know how this image related to Simple Pleasures.  Overall I like the cropping, the pose, and the expression on the model''s face very much.  The colors do look like they could use a bit more saturation.</td>', 'Back to comment: Sorry to be so blunt but without the title, I wouldn''t know how this image related to Simple Pleasures.  Overall I like the cropping, the pose, and the expression on the model''s face very much.  The colors do look like they could use a bit more saturation.', '2006-09-11 14:55:01.000000', NULL, 1),
(2824061, 391428, 20056, '<td valign="top">They do not look having any pleasure :)<br/>Nice photo anyway!</td>', 'They do not look having any pleasure :)Nice photo anyway!', '2006-09-11 14:55:59.000000', NULL, 1),
(2824069, 390695, 20056, '<td valign="top">Why to seat in stone when You have grass besisde? I can not keep that position for more than a minute :)<br/>Nice picture and idea</td>', 'Why to seat in stone when You have grass besisde? I can not keep that position for more than a minute :)Nice picture and idea', '2006-09-11 15:00:01.000000', NULL, 1),
(2824076, 389841, 61679, '<td valign="top">Back to comment: Sorry to be so blunt but this image comes across as harsh and not as pleasurable.  However, I didn''t factor this into my scoring.  On the technical side, the focus for this image appears to be misplaced.  The fingers are in sharper focus than the tomato itself.  Plus, the hand and tomato are a bit on the dark side.  It looks like your camera metered on the light in the background instead of your intended subject.  Next time you might want to use a fill flash to solve this problem.  Finally, the person in the background is distracting.  You will find with practice that you need to look at the background as much or more than the main subject itself.  Especially in challenges where you cannot clone objects out.</td>', 'Back to comment: Sorry to be so blunt but this image comes across as harsh and not as pleasurable.  However, I didn''t factor this into my scoring.  On the technical side, the focus for this image appears to be misplaced.  The fingers are in sharper focus than the tomato itself.  Plus, the hand and tomato are a bit on the dark side.  It looks like your camera metered on the light in the background instead of your intended subject.  Next time you might want to use a fill flash to solve this problem.  Finally, the person in the background is distracting.  You will find with practice that you need to look at the background as much or more than the main subject itself.  Especially in challenges where you cannot clone objects out.', '2006-09-11 15:02:15.000000', NULL, 1),
(2824106, 391486, 42100, '<td valign="top">Great b&amp;w tones and very soulful eyes.  Well done!</td>', 'Great b&w tones and very soulful eyes.  Well done!', '2006-09-11 15:10:53.000000', NULL, 1),
(2824107, 389157, 61679, '<td valign="top">Back to comment:  Although this subject fits the challenge well, there are a couple of technical issues that hurt your score.  First, it appears that the subject has considerable red-eye.  Second, the image is much smaller in size than the rules allow you to post.  This makes it difficult to judge the image and most voters will automatically vote low on small images.</td>', 'Back to comment:  Although this subject fits the challenge well, there are a couple of technical issues that hurt your score.  First, it appears that the subject has considerable red-eye.  Second, the image is much smaller in size than the rules allow you to post.  This makes it difficult to judge the image and most voters will automatically vote low on small images.', '2006-09-11 15:11:06.000000', NULL, 1),
(2824109, 391658, 61679, '<td valign="top">Back to comment: Sorry to be so blunt but this image has several technical issues that will negatively affect your score.  First, the sucker sticks blend into the white background and would not even be visible if it wasn''t for the shadows.  I would suggest using a light colored background next time (Light blue or green maybe).  Second, it looks like you arranged the candy in a pattern but the image wasn''t cropped symmetrically.  Third, the candy wasn''t really arranged in a manor that makes the voter''s wish they had thought to enter this image.</td>', 'Back to comment: Sorry to be so blunt but this image has several technical issues that will negatively affect your score.  First, the sucker sticks blend into the white background and would not even be visible if it wasn''t for the shadows.  I would suggest using a light colored background next time (Light blue or green maybe).  Second, it looks like you arranged the candy in a pattern but the image wasn''t cropped symmetrically.  Third, the candy wasn''t really arranged in a manor that makes the voter''s wish they had thought to enter this image.', '2006-09-11 15:11:11.000000', NULL, 1),
